import type { Catalog } from './i18n';

/**
 * French: every English text of the game (see i18n.ts) and its translation.
 *
 * Glossary (one French term per game term, used everywhere):
 * - Host: Hôte (capitalized, like the English); the Host is addressed with "tu" everywhere
 * - pilot (the clone in the cockpit): pilote; clone: clone (masculine)
 * - round: manche; tournament: tournoi; online tournament: tournoi en ligne; solo round: manche solo
 * - Deathmatch: Match à mort; Race: Course; Last Clone Standing: Dernier Clone Debout;
 *   Capture the Flag: Capture du drapeau; The President's Fleet: La Flotte du Président
 * - the Orange President: le Président Orange; United Solar States: États Solaires Unis;
 *   Ministry of War: ministère de la Guerre; Presidential Games: Jeux présidentiels
 * - flight school: École de pilotage; course (of the school): module; drill: exercice;
 *   Basic training / Racer / Gladiator / Arsenal / Tactician: Formation de base / Coureur / Gladiateur / Arsenal / Tacticien
 * - Hangar: Hangar; Solar Coins: Solar Coins (currency name kept); upgrade: amélioration;
 *   looks: apparence/style; The Sovereign: Le Souverain; interceptor: intercepteur
 * - drive / main drive: moteur / moteur principal; thrusters: propulseurs; radiators: radiateurs;
 *   armor: blindage; plating (extra plates from the hangar or a probe): surblindage;
 *   neon trim: liseré néon; drive flame: flamme du moteur; torpedo tubes: tubes lance-torpilles
 * - burn: poussée (pousser); flip: bascule (basculer); free drift: dérive libre;
 *   autopilot: pilote automatique (HUD: pilote auto); fine aim: visée fine; dodge: esquive;
 *   overdrive: surrégime; course (the flight's direction marker): cap; velocity: vitesse
 * - hook: grappin (harpoon: harpon, winch: treuil, cable: câble; hooked: accroché);
 *   torpedo: torpille; lock: verrouillage; probe: sonde; nova core: noyau nova;
 *   sponsor core (Capture the Flag): noyau de sponsor, noyau; base/home: base
 * - gate: porte; ring: anneau; coil: bobine; lap: tour; start/finish: départ/arrivée; GO: PARTEZ
 * - battleship: cuirassé; battery: batterie; reactor: réacteur; drive plume: panache
 * - solar flare: éruption solaire; live link: liaison directe; kill: élimination; dogfight: duel
 * - Aim / Reflexes / Daring: Visée / Réflexes / Audace; Orange / Blue (sides): Orange / Bleu
 * - Radio 2584 announcer: commentateur (addresses the audience and pilots with "vous");
 *   Nicole calls the Host "mon chéri"
 * Ordinals: places only run up to the size of a tournament (8), so '{n}st' is always 1st: 1er, 2e, 3e…
 * Key names stay as printed on keyboards and pads (Esc, Enter, Tab, Shift, RT…); Space is Espace.
 * Typography: a no-break space ( ) before : ; ? ! and inside « », so justified text never
 * breaks a line there.
 */
